-- =====================================================================
--  COBUILD — full database setup
-- ---------------------------------------------------------------------
--  Paste this whole file into Supabase → SQL Editor → Run.
--
--  • Safe to run more than once (everything is "if not exists" /
--    "create or replace" / "drop policy if exists").
--  • Works on your existing SkillMatch database AND on a brand-new
--    Supabase project (it creates the base tables if they're missing).
--  • The one-time reset at the bottom (delete all old projects, then
--    import open-source projects from GitHub) only runs once — a marker
--    row in cb_migrations stops it from wiping projects on a re-run.
-- =====================================================================


-- =====================================================================
-- 1. BASE TABLES (only created if they don't exist yet)
-- =====================================================================

create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  name text,
  avatar_url text,
  bio text,
  primary_role text,
  goal text,
  created_at timestamptz not null default now()
);

create table if not exists public.skills (
  id bigint generated by default as identity primary key,
  name text not null
);

create table if not exists public.user_skills (
  user_id uuid not null references public.profiles(id) on delete cascade,
  skill_id bigint not null references public.skills(id) on delete cascade,
  primary key (user_id, skill_id)
);

create table if not exists public.projects (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid references public.profiles(id) on delete cascade,
  title text not null,
  description text,
  status text default 'open',
  created_at timestamptz not null default now()
);

create table if not exists public.project_roles_needed (
  id bigint generated by default as identity primary key,
  project_id uuid not null references public.projects(id) on delete cascade,
  role_name text not null
);

create table if not exists public.project_members (
  project_id uuid not null references public.projects(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  role text,
  joined_at timestamptz not null default now(),
  primary key (project_id, user_id)
);

create table if not exists public.applications (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.projects(id) on delete cascade,
  applicant_id uuid not null references public.profiles(id) on delete cascade,
  message text,
  status text not null default 'pending',
  created_at timestamptz not null default now(),
  unique (project_id, applicant_id)
);

create table if not exists public.messages (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.projects(id) on delete cascade,
  sender_id uuid not null references public.profiles(id) on delete cascade,
  text text not null,
  created_at timestamptz not null default now()
);

alter table public.profiles enable row level security;
alter table public.skills enable row level security;
alter table public.user_skills enable row level security;
alter table public.projects enable row level security;
alter table public.project_roles_needed enable row level security;
alter table public.project_members enable row level security;
alter table public.applications enable row level security;
alter table public.messages enable row level security;

-- Imported open-source projects have no owner inside the app.
alter table public.projects alter column owner_id drop not null;

-- If status was created as a custom enum type, store it as plain text instead
-- (the app writes 'open' / 'in_progress' / 'closed').
do $$
begin
  if (select data_type from information_schema.columns
      where table_schema = 'public' and table_name = 'projects' and column_name = 'status') = 'USER-DEFINED' then
    alter table public.projects alter column status drop default;
    alter table public.projects alter column status type text using status::text;
    alter table public.projects alter column status set default 'open';
  end if;
end $$;

-- Any older foreign key that points at projects without ON DELETE CASCADE
-- would block deleting a project. Convert those (NO ACTION / RESTRICT only)
-- to CASCADE so "delete project" works everywhere.
do $$
declare r record;
begin
  for r in
    select c.conname, c.conrelid::regclass as tbl, pg_get_constraintdef(c.oid) as def
    from pg_constraint c
    where c.contype = 'f'
      and c.confrelid = 'public.projects'::regclass
      and c.confdeltype in ('a', 'r')
  loop
    execute format('alter table %s drop constraint %I', r.tbl, r.conname);
    execute format('alter table %s add constraint %I %s on delete cascade',
                   r.tbl, r.conname,
                   regexp_replace(r.def, '\s+ON DELETE (NO ACTION|RESTRICT)', '', 'i'));
  end loop;
end $$;

-- Base row-level security (prefixed "cb:" so re-runs replace them cleanly)
drop policy if exists "cb: profiles readable" on public.profiles;
create policy "cb: profiles readable" on public.profiles for select to authenticated using (true);
drop policy if exists "cb: insert own profile" on public.profiles;
create policy "cb: insert own profile" on public.profiles for insert to authenticated with check (auth.uid() = id);
drop policy if exists "cb: update own profile" on public.profiles;
create policy "cb: update own profile" on public.profiles for update to authenticated using (auth.uid() = id) with check (auth.uid() = id);

drop policy if exists "cb: skills readable" on public.skills;
create policy "cb: skills readable" on public.skills for select to authenticated using (true);

drop policy if exists "cb: user_skills readable" on public.user_skills;
create policy "cb: user_skills readable" on public.user_skills for select to authenticated using (true);
drop policy if exists "cb: add own skills" on public.user_skills;
create policy "cb: add own skills" on public.user_skills for insert to authenticated with check (auth.uid() = user_id);
drop policy if exists "cb: remove own skills" on public.user_skills;
create policy "cb: remove own skills" on public.user_skills for delete to authenticated using (auth.uid() = user_id);

drop policy if exists "cb: projects readable" on public.projects;
create policy "cb: projects readable" on public.projects for select to authenticated using (true);
drop policy if exists "cb: create own projects" on public.projects;
create policy "cb: create own projects" on public.projects for insert to authenticated with check (auth.uid() = owner_id);
drop policy if exists "cb: owners update projects" on public.projects;
create policy "cb: owners update projects" on public.projects for update to authenticated using (auth.uid() = owner_id) with check (auth.uid() = owner_id);
drop policy if exists "cb: owners delete projects" on public.projects;
create policy "cb: owners delete projects" on public.projects for delete to authenticated using (auth.uid() = owner_id);

drop policy if exists "cb: roles readable" on public.project_roles_needed;
create policy "cb: roles readable" on public.project_roles_needed for select to authenticated using (true);
drop policy if exists "cb: owners add roles" on public.project_roles_needed;
create policy "cb: owners add roles" on public.project_roles_needed for insert to authenticated
  with check (exists (select 1 from public.projects p where p.id = project_id and p.owner_id = auth.uid()));
drop policy if exists "cb: owners remove roles" on public.project_roles_needed;
create policy "cb: owners remove roles" on public.project_roles_needed for delete to authenticated
  using (exists (select 1 from public.projects p where p.id = project_id and p.owner_id = auth.uid()));

drop policy if exists "cb: members readable" on public.project_members;
create policy "cb: members readable" on public.project_members for select to authenticated using (true);
drop policy if exists "cb: owners add members" on public.project_members;
create policy "cb: owners add members" on public.project_members for insert to authenticated
  with check (exists (select 1 from public.projects p where p.id = project_id and p.owner_id = auth.uid()));
drop policy if exists "cb: owners or self remove members" on public.project_members;
create policy "cb: owners or self remove members" on public.project_members for delete to authenticated
  using (auth.uid() = user_id or exists (select 1 from public.projects p where p.id = project_id and p.owner_id = auth.uid()));

drop policy if exists "cb: applicant or owner reads application" on public.applications;
create policy "cb: applicant or owner reads application" on public.applications for select to authenticated
  using (auth.uid() = applicant_id or exists (select 1 from public.projects p where p.id = project_id and p.owner_id = auth.uid()));
drop policy if exists "cb: apply as yourself" on public.applications;
create policy "cb: apply as yourself" on public.applications for insert to authenticated with check (auth.uid() = applicant_id);
drop policy if exists "cb: owner decides application" on public.applications;
create policy "cb: owner decides application" on public.applications for update to authenticated
  using (exists (select 1 from public.projects p where p.id = project_id and p.owner_id = auth.uid()));
drop policy if exists "cb: applicant withdraws" on public.applications;
create policy "cb: applicant withdraws" on public.applications for delete to authenticated using (auth.uid() = applicant_id);

drop policy if exists "cb: team reads chat" on public.messages;
create policy "cb: team reads chat" on public.messages for select to authenticated
  using (exists (select 1 from public.project_members m where m.project_id = messages.project_id and m.user_id = auth.uid()));
drop policy if exists "cb: team writes chat" on public.messages;
create policy "cb: team writes chat" on public.messages for insert to authenticated
  with check (auth.uid() = sender_id and exists (select 1 from public.project_members m where m.project_id = messages.project_id and m.user_id = auth.uid()));

