-- =====================================================================
-- 2. MIGRATIONS 002–004 (saved projects, DMs, notifications, reads)
-- =====================================================================

create table if not exists public.saved_projects (
  user_id uuid not null references public.profiles(id) on delete cascade,
  project_id uuid not null references public.projects(id) on delete cascade,
  saved_at timestamptz default now(),
  primary key (user_id, project_id)
);
alter table public.saved_projects enable row level security;
drop policy if exists "Users can view their own saved projects" on public.saved_projects;
create policy "Users can view their own saved projects" on public.saved_projects for select using (auth.uid() = user_id);
drop policy if exists "Users can save projects for themselves" on public.saved_projects;
create policy "Users can save projects for themselves" on public.saved_projects for insert with check (auth.uid() = user_id);
drop policy if exists "Users can unsave their own saved projects" on public.saved_projects;
create policy "Users can unsave their own saved projects" on public.saved_projects for delete using (auth.uid() = user_id);
create index if not exists idx_saved_projects_user on public.saved_projects (user_id);

-- Application threads (owner <-> applicant, scoped to one project)
create table if not exists public.direct_messages (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.projects(id) on delete cascade,
  applicant_id uuid not null references public.profiles(id) on delete cascade,
  sender_id uuid not null references public.profiles(id) on delete cascade,
  text text not null,
  created_at timestamptz default now()
);
alter table public.direct_messages enable row level security;
drop policy if exists "Owner or applicant can view their thread" on public.direct_messages;
create policy "Owner or applicant can view their thread" on public.direct_messages for select
  using (auth.uid() = applicant_id or auth.uid() = (select owner_id from public.projects where id = project_id));
drop policy if exists "Owner or applicant can send in their thread" on public.direct_messages;
create policy "Owner or applicant can send in their thread" on public.direct_messages for insert
  with check (auth.uid() = sender_id and (auth.uid() = applicant_id or auth.uid() = (select owner_id from public.projects where id = project_id)));
create index if not exists idx_direct_messages_thread on public.direct_messages (project_id, applicant_id, created_at);

create table if not exists public.notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  type text not null,
  title text not null,
  body text,
  project_id uuid references public.projects(id) on delete cascade,
  is_read boolean default false,
  created_at timestamptz default now()
);
alter table public.notifications add column if not exists link text;
alter table public.notifications enable row level security;
drop policy if exists "Users can view their own notifications" on public.notifications;
create policy "Users can view their own notifications" on public.notifications for select using (auth.uid() = user_id);
drop policy if exists "Users can mark their own notifications read" on public.notifications;
create policy "Users can mark their own notifications read" on public.notifications for update using (auth.uid() = user_id);
create index if not exists idx_notifications_user on public.notifications (user_id, created_at desc);

create table if not exists public.chat_reads (
  user_id uuid not null references public.profiles(id) on delete cascade,
  project_id uuid not null references public.projects(id) on delete cascade,
  last_read_at timestamptz default now(),
  primary key (user_id, project_id)
);
alter table public.chat_reads enable row level security;
drop policy if exists "Users can view their own read state" on public.chat_reads;
create policy "Users can view their own read state" on public.chat_reads for select using (auth.uid() = user_id);
drop policy if exists "Users can upsert their own read state" on public.chat_reads;
create policy "Users can upsert their own read state" on public.chat_reads for insert with check (auth.uid() = user_id);
drop policy if exists "Users can update their own read state" on public.chat_reads;
create policy "Users can update their own read state" on public.chat_reads for update using (auth.uid() = user_id);

create table if not exists public.account_deletion_requests (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  reason text,
  requested_at timestamptz default now(),
  status text default 'pending'
);
alter table public.account_deletion_requests enable row level security;
drop policy if exists "Users can request deletion of their own account" on public.account_deletion_requests;
create policy "Users can request deletion of their own account" on public.account_deletion_requests for insert with check (auth.uid() = user_id);
drop policy if exists "Users can view their own deletion request" on public.account_deletion_requests;
create policy "Users can view their own deletion request" on public.account_deletion_requests for select using (auth.uid() = user_id);

-- Avatar storage (wrapped so a storage permission quirk can't stop the rest of the script)
do $$
begin
  insert into storage.buckets (id, name, public) values ('avatars', 'avatars', true) on conflict (id) do nothing;
  drop policy if exists "Avatar images are publicly accessible" on storage.objects;
  create policy "Avatar images are publicly accessible" on storage.objects for select using (bucket_id = 'avatars');
  drop policy if exists "Users can upload their own avatar" on storage.objects;
  create policy "Users can upload their own avatar" on storage.objects for insert
    with check (bucket_id = 'avatars' and auth.uid()::text = (storage.foldername(name))[1]);
  drop policy if exists "Users can update their own avatar" on storage.objects;
  create policy "Users can update their own avatar" on storage.objects for update
    using (bucket_id = 'avatars' and auth.uid()::text = (storage.foldername(name))[1]);
exception when others then
  raise notice 'Skipped avatar storage policies (%). Create the "avatars" bucket in Storage if uploads fail.', sqlerrm;
end $$;


