create unique index if not exists profiles_username_lower_key on public.profiles (lower(username)) where username is not null;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'profiles_username_format') then
    alter table public.profiles add constraint profiles_username_format
      check (username is null or username ~ '^[a-z0-9_]{3,20}$') not valid;
  end if;
end $$;

-- Every new auth user gets a profile row straight away.
-- Named "zz_..." so it runs AFTER any profile trigger you already had, and it
-- swallows its own errors so it can never block a signup.
create or replace function public.cb_handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  begin
    insert into public.profiles (id) values (new.id) on conflict (id) do nothing;
  exception when others then
    raise warning 'cb_handle_new_user skipped: %', sqlerrm;
  end;
  return new;
end $$;

drop trigger if exists cb_on_auth_user_created on auth.users;
drop trigger if exists zz_cb_on_auth_user_created on auth.users;
create trigger zz_cb_on_auth_user_created after insert on auth.users
  for each row execute function public.cb_handle_new_user();

-- Backfill: any existing user without a profile row gets one.
do $$
begin
  insert into public.profiles (id)
  select u.id from auth.users u
  where not exists (select 1 from public.profiles p where p.id = u.id);
exception when others then
  raise notice 'Profile backfill skipped (%). Users will create their profile during onboarding.', sqlerrm;
end $$;


