create table if not exists public.app_admins (
  user_id uuid primary key references public.profiles(id) on delete cascade,
  added_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now()
);
alter table public.app_admins enable row level security;
drop policy if exists "cb: admins list readable" on public.app_admins;
create policy "cb: admins list readable" on public.app_admins for select to authenticated using (true);

-- Emails that become admin automatically (now, or the moment they sign up).
-- No policies = invisible to the app; only the SQL editor can change it.
create table if not exists public.admin_bootstrap_emails (email text primary key);
alter table public.admin_bootstrap_emails enable row level security;
insert into public.admin_bootstrap_emails (email) values ('wisdomudoudo24@gmail.com') on conflict do nothing;

create or replace function public.is_admin(uid uuid default auth.uid())
returns boolean language sql stable security definer set search_path = public as $$
  select uid is not null and exists (select 1 from public.app_admins a where a.user_id = uid);
$$;

create or replace function public.cb_require_admin()
returns void language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_admin() then
    raise exception 'Admins only.' using errcode = '42501';
  end if;
end $$;

create or replace function public.cb_grant_bootstrap_admin()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if exists (
    select 1 from auth.users u
    join public.admin_bootstrap_emails b on lower(b.email) = lower(u.email)
    where u.id = new.id
  ) then
    insert into public.app_admins (user_id) values (new.id) on conflict do nothing;
  end if;
  return new;
end $$;

drop trigger if exists cb_grant_bootstrap_admin on public.profiles;
create trigger cb_grant_bootstrap_admin after insert on public.profiles
  for each row execute function public.cb_grant_bootstrap_admin();

insert into public.app_admins (user_id)
select p.id from public.profiles p
join auth.users u on u.id = p.id
join public.admin_bootstrap_emails b on lower(b.email) = lower(u.email)
on conflict do nothing;


-- =====================================================================
-- 5. ACTIVITY (streaks) + PRESENCE (active users)
-- =====================================================================

-- One row per user per day they contributed (post, ship, create...). Powers streaks.
create table if not exists public.activity_days (
  user_id uuid not null references public.profiles(id) on delete cascade,
  day date not null default current_date,
  primary key (user_id, day)
);
alter table public.activity_days enable row level security;
drop policy if exists "cb: activity readable" on public.activity_days;
create policy "cb: activity readable" on public.activity_days for select to authenticated using (true);

-- One row per user per day they opened the app. Powers DAU / WAU / MAU for admins.
create table if not exists public.user_visits (
  user_id uuid not null references public.profiles(id) on delete cascade,
  day date not null default current_date,
  primary key (user_id, day)
);
alter table public.user_visits enable row level security;

create or replace function public.cb_mark_active(uid uuid)
returns void language sql security definer set search_path = public as $$
  insert into public.activity_days (user_id, day) select uid, current_date where uid is not null
  on conflict do nothing;
$$;

create or replace function public.touch_presence()
returns void language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then return; end if;
  update public.profiles set last_seen_at = now() where id = auth.uid();
  insert into public.user_visits (user_id, day) values (auth.uid(), current_date) on conflict do nothing;
end $$;

create or replace function public.get_online_count()
returns int language sql stable security definer set search_path = public as $$
  select count(*)::int from public.profiles
  where last_seen_at > now() - interval '3 minutes' and show_online;
$$;


