-- Users can't fake progress, featuring, or the GitHub source fields.
create or replace function public.cb_projects_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    if auth.uid() is not null and not public.is_admin() then
      new.is_featured := false;
      new.source := 'community';
      new.external_url := null;
      new.external_owner := null;
      new.external_stars := null;
      new.external_contribute_url := null;
      new.external_source := null;
      new.progress := 0;
    end if;
  else
    -- progress only changes when the milestone trigger updates it (nested depth 2)
    if pg_trigger_depth() < 2 then
      new.progress := old.progress;
    end if;
    if auth.uid() is not null and not public.is_admin() then
      new.is_featured := old.is_featured;
      new.source := old.source;
      new.external_url := old.external_url;
      new.external_owner := old.external_owner;
      new.external_stars := old.external_stars;
      new.external_contribute_url := old.external_contribute_url;
      new.external_source := old.external_source;
    end if;
    new.updated_at := now();
  end if;
  return new;
end $$;

drop trigger if exists cb_projects_guard on public.projects;
create trigger cb_projects_guard before insert or update on public.projects
  for each row execute function public.cb_projects_guard();

-- Roadmap weights can never add up to more than 100%.
create or replace function public.cb_milestones_sum_check()
returns trigger language plpgsql as $$
declare total int;
begin
  select coalesce(sum(weight), 0) into total from public.project_milestones where project_id = new.project_id;
  if total > 100 then
    raise exception '%', format('Roadmap steps can''t add up to more than 100%% (currently %s%%).', total);
  end if;
  return null;
end $$;

drop trigger if exists cb_milestones_sum_check on public.project_milestones;
create trigger cb_milestones_sum_check after insert or update of weight on public.project_milestones
  for each row execute function public.cb_milestones_sum_check();

-- Progress = sum of the weights of finished steps.
create or replace function public.cb_recalc_progress()
returns trigger language plpgsql security definer set search_path = public as $$
declare pid uuid;
begin
  if tg_op = 'DELETE' then pid := old.project_id; else pid := new.project_id; end if;
  update public.projects
     set progress = least(100, (select coalesce(sum(weight), 0) from public.project_milestones where project_id = pid and is_done))
   where id = pid;
  return null;
end $$;

drop trigger if exists cb_recalc_progress on public.project_milestones;
create trigger cb_recalc_progress after insert or update or delete on public.project_milestones
  for each row execute function public.cb_recalc_progress();

-- Applying only makes sense for community projects you don't own.
create or replace function public.cb_applications_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if exists (select 1 from public.projects where id = new.project_id and (source <> 'community' or owner_id is null)) then
    raise exception 'This project is run outside Cobuild — use its link to contribute.';
  end if;
  if exists (select 1 from public.projects where id = new.project_id and owner_id = new.applicant_id) then
    raise exception 'You already own this project.';
  end if;
  return new;
end $$;

drop trigger if exists cb_applications_guard on public.applications;
create trigger cb_applications_guard before insert on public.applications
  for each row execute function public.cb_applications_guard();

-- Shared validation for create/update.
create or replace function public.cb_clean_url(u text)
returns text language sql immutable as $$
  select case
    when u is null or btrim(u) = '' then null
    when btrim(u) ~* '^https?://[^\s]+$' then btrim(u)
    else 'https://' || btrim(u)
  end;
$$;

create or replace function public.cb_validate_project(p jsonb)
returns void language plpgsql as $$
declare total int; n int;
begin
  if coalesce(btrim(p->>'title'), '') = '' then raise exception 'Give your project a name.'; end if;
  if char_length(btrim(p->>'title')) > 80 then raise exception 'Project name must be 80 characters or less.'; end if;
  if coalesce(btrim(p->>'description'), '') = '' then raise exception 'Describe what you''re building.'; end if;
  if char_length(p->>'description') > 4000 then raise exception 'Description must be 4000 characters or less.'; end if;
  if coalesce(p->>'stage', 'building') not in ('idea', 'building', 'beta', 'launched') then raise exception 'Pick a valid stage.'; end if;
  if coalesce(p->>'status', 'open') not in ('open', 'in_progress', 'closed') then raise exception 'Pick a valid status.'; end if;
  if jsonb_typeof(p->'milestones') is distinct from 'array' or jsonb_array_length(p->'milestones') = 0 then
    raise exception 'Add at least one roadmap step.';
  end if;
  n := jsonb_array_length(p->'milestones');
  if n > 30 then raise exception 'A roadmap can have at most 30 steps.'; end if;
  if exists (select 1 from jsonb_array_elements(p->'milestones') x
             where coalesce(btrim(x->>'title'), '') = '' or char_length(x->>'title') > 140) then
    raise exception 'Every roadmap step needs a name (max 140 characters).';
  end if;
  if exists (select 1 from jsonb_array_elements(p->'milestones') x
             where coalesce((x->>'weight')::int, 0) < 1 or (x->>'weight')::int > 100) then
    raise exception 'Each roadmap step must be worth between 1%% and 100%%.';
  end if;
  select coalesce(sum((x->>'weight')::int), 0) into total from jsonb_array_elements(p->'milestones') x;
  if total <> 100 then
    raise exception '%', format('Roadmap steps must add up to exactly 100%% (yours add up to %s%%).', total);
  end if;
end $$;

create or replace function public.create_project(p jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  new_id uuid;
begin
  if uid is null then raise exception 'Please sign in first.'; end if;
  perform public.cb_validate_project(p);

  insert into public.projects (owner_id, title, tagline, description, category, stage, status,
                               tech_stack, repo_url, demo_url, source)
  values (
    uid,
    btrim(p->>'title'),
    nullif(btrim(coalesce(p->>'tagline', '')), ''),
    btrim(p->>'description'),
    nullif(btrim(coalesce(p->>'category', '')), ''),
    coalesce(p->>'stage', 'building'),
    coalesce(p->>'status', 'open'),
    coalesce((select array_agg(distinct btrim(t)) from jsonb_array_elements_text(coalesce(p->'tech_stack', '[]')) t where btrim(t) <> ''), '{}'),
    public.cb_clean_url(p->>'repo_url'),
    public.cb_clean_url(p->>'demo_url'),
    'community'
  )
  returning id into new_id;

  insert into public.project_roles_needed (project_id, role_name)
  select new_id, r from (
    select distinct btrim(t) as r from jsonb_array_elements_text(coalesce(p->'roles', '[]')) t where btrim(t) <> ''
  ) s;

  insert into public.project_members (project_id, user_id, role) values (new_id, uid, 'Owner')
  on conflict do nothing;

  insert into public.project_milestones (project_id, title, description, weight, position)
  select new_id, btrim(x->>'title'), nullif(btrim(coalesce(x->>'description', '')), ''), (x->>'weight')::int, (ord - 1)::int
  from jsonb_array_elements(p->'milestones') with ordinality as m(x, ord);

  perform public.cb_mark_active(uid);
  return new_id;
end $$;

create or replace function public.update_project(p_id uuid, p jsonb)
returns void language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  owner uuid;
begin
  select owner_id into owner from public.projects where id = p_id;
  if not found then raise exception 'Project not found.'; end if;
  if uid is null or (owner is distinct from uid and not public.is_admin()) then
    raise exception 'Only the project owner can edit this project.' using errcode = '42501';
  end if;
  perform public.cb_validate_project(p);

  update public.projects set
    title = btrim(p->>'title'),
    tagline = nullif(btrim(coalesce(p->>'tagline', '')), ''),
    description = btrim(p->>'description'),
    category = nullif(btrim(coalesce(p->>'category', '')), ''),
    stage = coalesce(p->>'stage', 'building'),
    status = coalesce(p->>'status', 'open'),
    tech_stack = coalesce((select array_agg(distinct btrim(t)) from jsonb_array_elements_text(coalesce(p->'tech_stack', '[]')) t where btrim(t) <> ''), '{}'),
    repo_url = public.cb_clean_url(p->>'repo_url'),
    demo_url = public.cb_clean_url(p->>'demo_url')
  where id = p_id;

  delete from public.project_roles_needed where project_id = p_id;
  insert into public.project_roles_needed (project_id, role_name)
  select p_id, r from (
    select distinct btrim(t) as r from jsonb_array_elements_text(coalesce(p->'roles', '[]')) t where btrim(t) <> ''
  ) s;

  -- Roadmap: keep finished state for steps that still exist (matched by id).
  delete from public.project_milestones m
  where m.project_id = p_id
    and m.id not in (
      select (x->>'id')::uuid from jsonb_array_elements(p->'milestones') x
      where coalesce(x->>'id', '') ~ '^[0-9a-f-]{36}$'
    );

  update public.project_milestones m set
    title = btrim(x.item->>'title'),
    description = nullif(btrim(coalesce(x.item->>'description', '')), ''),
    weight = (x.item->>'weight')::int,
    position = (x.ord - 1)::int
  from jsonb_array_elements(p->'milestones') with ordinality as x(item, ord)
  where m.project_id = p_id
    and coalesce(x.item->>'id', '') ~ '^[0-9a-f-]{36}$'
    and m.id = (x.item->>'id')::uuid;

  insert into public.project_milestones (project_id, title, description, weight, position)
  select p_id, btrim(x.item->>'title'), nullif(btrim(coalesce(x.item->>'description', '')), ''), (x.item->>'weight')::int, (x.ord - 1)::int
  from jsonb_array_elements(p->'milestones') with ordinality as x(item, ord)
  where not (coalesce(x.item->>'id', '') ~ '^[0-9a-f-]{36}$'
             and exists (select 1 from public.project_milestones m where m.id = (x.item->>'id')::uuid and m.project_id = p_id));
end $$;

create or replace function public.delete_project(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare owner uuid;
begin
  select owner_id into owner from public.projects where id = p_id;
  if not found then return; end if;
  if auth.uid() is null or (owner is distinct from auth.uid() and not public.is_admin()) then
    raise exception 'Only the project owner can delete this project.' using errcode = '42501';
  end if;
  delete from public.projects where id = p_id;
end $$;

-- Tick a roadmap step done / not done. Owner and team members can do this.
create or replace function public.set_milestone_done(p_milestone_id uuid, p_done boolean)
returns int language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  m record;
  pr record;
  new_progress int;
begin
  select * into m from public.project_milestones where id = p_milestone_id;
  if not found then raise exception 'Roadmap step not found.'; end if;
  select * into pr from public.projects where id = m.project_id;
  if uid is null or not (
    pr.owner_id = uid
    or exists (select 1 from public.project_members pm where pm.project_id = pr.id and pm.user_id = uid)
    or public.is_admin()
  ) then
    raise exception 'Only the project team can update the roadmap.' using errcode = '42501';
  end if;

  if m.is_done = p_done then
    return pr.progress;
  end if;

  update public.project_milestones
     set is_done = p_done,
         done_at = case when p_done then now() else null end,
         done_by = case when p_done then uid else null end
   where id = p_milestone_id;

  select progress into new_progress from public.projects where id = pr.id;

  if p_done then
    perform public.cb_mark_active(uid);
    insert into public.notifications (user_id, type, title, body, project_id, link)
    select pm.user_id, 'milestone_done',
           case when new_progress >= 100 then pr.title || ' hit 100%' else 'Roadmap step shipped' end,
           coalesce((select name from public.profiles where id = uid), 'A teammate') || ' finished "' || m.title || '" — ' || pr.title || ' is now ' || new_progress || '% done',
           pr.id, '/project/' || pr.id
    from public.project_members pm
    where pm.project_id = pr.id and pm.user_id <> uid;
  end if;

  return new_progress;
end $$;

-- Upvote ("hype") notifications for the owner.
create or replace function public.cb_on_project_upvote()
returns trigger language plpgsql security definer set search_path = public as $$
declare pr record;
begin
  select id, title, owner_id into pr from public.projects where id = new.project_id;
  if pr.owner_id is not null and pr.owner_id <> new.user_id then
    insert into public.notifications (user_id, type, title, body, project_id, link)
    values (pr.owner_id, 'project_upvote', 'Your project got hyped',
            coalesce((select name from public.profiles where id = new.user_id), 'Someone') || ' hyped ' || pr.title,
            pr.id, '/project/' || pr.id);
  end if;
  return new;
end $$;

drop trigger if exists cb_on_project_upvote on public.project_upvotes;
create trigger cb_on_project_upvote after insert on public.project_upvotes
  for each row execute function public.cb_on_project_upvote();

-- Team chat counts towards your streak.
create or replace function public.cb_on_team_message()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  perform public.cb_mark_active(new.sender_id);
  return new;
end $$;

drop trigger if exists cb_on_team_message on public.messages;
create trigger cb_on_team_message after insert on public.messages
  for each row execute function public.cb_on_team_message();

-- Updated versions of the older notification triggers (null-owner safe,
-- and imported GitHub projects never spam "matches your skills").
create or replace function public.notify_owner_on_application()
returns trigger as $$
begin
  insert into public.notifications (user_id, type, title, body, project_id, link)
  select p.owner_id, 'application_received', 'New application',
         coalesce((select name from public.profiles where id = new.applicant_id), 'Someone') || ' applied to ' || p.title,
         p.id, '/project/' || p.id || '/applications'
  from public.projects p where p.id = new.project_id and p.owner_id is not null;
  return new;
end;
$$ language plpgsql security definer set search_path = public;

drop trigger if exists trg_notify_owner_on_application on public.applications;
create trigger trg_notify_owner_on_application after insert on public.applications
  for each row execute function public.notify_owner_on_application();

create or replace function public.notify_applicant_on_status_change()
returns trigger as $$
begin
  if new.status is distinct from old.status and new.status in ('accepted', 'rejected') then
    insert into public.notifications (user_id, type, title, body, project_id, link)
    select new.applicant_id, 'application_status',
           case when new.status = 'accepted' then 'You''re on the team!' else 'Application update' end,
           case when new.status = 'accepted' then 'You were accepted to ' || p.title || '. Say hi in the team chat.'
                else 'Your application to ' || p.title || ' wasn''t accepted this time.' end,
           p.id, '/project/' || p.id
    from public.projects p where p.id = new.project_id;
  end if;
  return new;
end;
$$ language plpgsql security definer set search_path = public;

drop trigger if exists trg_notify_applicant_on_status on public.applications;
create trigger trg_notify_applicant_on_status after update on public.applications
  for each row execute function public.notify_applicant_on_status_change();

create or replace function public.notify_on_direct_message()
returns trigger as $$
declare
  recipient uuid;
  owner uuid;
begin
  select owner_id into owner from public.projects where id = new.project_id;
  recipient := case when new.sender_id = new.applicant_id then owner else new.applicant_id end;
  if recipient is not null and recipient <> new.sender_id then
    insert into public.notifications (user_id, type, title, body, project_id, link)
    values (recipient, 'direct_message', 'New message', left(new.text, 140), new.project_id,
            '/project/' || new.project_id || '/messages/' || new.applicant_id);
  end if;
  return new;
end;
$$ language plpgsql security definer set search_path = public;

drop trigger if exists trg_notify_on_direct_message on public.direct_messages;
create trigger trg_notify_on_direct_message after insert on public.direct_messages
  for each row execute function public.notify_on_direct_message();

create or replace function public.notify_matching_users_on_role_added()
returns trigger as $$
begin
  insert into public.notifications (user_id, type, title, body, project_id, link)
  select distinct pr.id, 'project_match', 'A project needs your skills',
         p.title || ' is looking for a ' || new.role_name,
         new.project_id, '/project/' || new.project_id
  from public.profiles pr
  join public.projects p on p.id = new.project_id
  where p.source = 'community'
    and p.owner_id is not null
    and pr.id <> p.owner_id
    and (
      (pr.primary_role is not null and pr.primary_role ilike new.role_name)
      or exists (
        select 1 from public.user_skills us
        join public.skills s on s.id = us.skill_id
        where us.user_id = pr.id and s.name ilike new.role_name
      )
    )
    and not exists (
      select 1 from public.notifications n
      where n.user_id = pr.id and n.project_id = new.project_id and n.type = 'project_match'
    );
  return new;
end;
$$ language plpgsql security definer set search_path = public;

drop trigger if exists trg_notify_matching_users on public.project_roles_needed;
create trigger trg_notify_matching_users after insert on public.project_roles_needed
  for each row execute function public.notify_matching_users_on_role_added();


-- =====================================================================
-- 7. COMMUNITY: rooms, posts, likes, unread
-- =====================================================================

create table if not exists public.community_rooms (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique check (slug ~ '^[a-z0-9-]{2,40}$'),
  name text not null,
  description text,
  category text not null default 'Community',
  is_locked boolean not null default false,
  position int not null default 0,
  created_at timestamptz not null default now()
);
alter table public.community_rooms enable row level security;
drop policy if exists "cb: rooms readable" on public.community_rooms;
create policy "cb: rooms readable" on public.community_rooms for select to authenticated using (true);
drop policy if exists "cb: admins manage rooms" on public.community_rooms;
create policy "cb: admins manage rooms" on public.community_rooms for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

create table if not exists public.community_messages (
  id uuid primary key default gen_random_uuid(),
  room_id uuid not null references public.community_rooms(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  body text not null check (char_length(btrim(body)) between 1 and 2000),
  reply_to uuid references public.community_messages(id) on delete set null,
  created_at timestamptz not null default now()
);
create index if not exists idx_community_messages_room on public.community_messages (room_id, created_at desc);
create index if not exists idx_community_messages_user on public.community_messages (user_id, created_at desc);
alter table public.community_messages enable row level security;
drop policy if exists "cb: posts readable" on public.community_messages;
create policy "cb: posts readable" on public.community_messages for select to authenticated using (true);
drop policy if exists "cb: post as yourself" on public.community_messages;
create policy "cb: post as yourself" on public.community_messages for insert to authenticated
  with check (
    auth.uid() = user_id
    and (public.is_admin() or not exists (select 1 from public.community_rooms r where r.id = room_id and r.is_locked))
  );
drop policy if exists "cb: delete own post or admin" on public.community_messages;
create policy "cb: delete own post or admin" on public.community_messages for delete to authenticated
  using (auth.uid() = user_id or public.is_admin());

create table if not exists public.community_message_likes (
  message_id uuid not null references public.community_messages(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (message_id, user_id)
);
alter table public.community_message_likes enable row level security;
drop policy if exists "cb: likes readable" on public.community_message_likes;
create policy "cb: likes readable" on public.community_message_likes for select to authenticated using (true);
drop policy if exists "cb: like as yourself" on public.community_message_likes;
create policy "cb: like as yourself" on public.community_message_likes for insert to authenticated with check (auth.uid() = user_id);
drop policy if exists "cb: unlike own" on public.community_message_likes;
create policy "cb: unlike own" on public.community_message_likes for delete to authenticated using (auth.uid() = user_id);

create table if not exists public.community_room_reads (
  user_id uuid not null references public.profiles(id) on delete cascade,
  room_id uuid not null references public.community_rooms(id) on delete cascade,
  last_read_at timestamptz not null default now(),
  primary key (user_id, room_id)
);
alter table public.community_room_reads enable row level security;
drop policy if exists "cb: own room reads" on public.community_room_reads;
create policy "cb: own room reads" on public.community_room_reads for all to authenticated
  using (auth.uid() = user_id) with check (auth.uid() = user_id);

create or replace function public.cb_on_community_message()
returns trigger language plpgsql security definer set search_path = public as $$
declare parent_author uuid; room_name text; room_slug text;
begin
  perform public.cb_mark_active(new.user_id);
  if new.reply_to is not null then
    select user_id into parent_author from public.community_messages where id = new.reply_to;
    select name, slug into room_name, room_slug from public.community_rooms where id = new.room_id;
    if parent_author is not null and parent_author <> new.user_id then
      insert into public.notifications (user_id, type, title, body, link)
      values (parent_author, 'community_reply',
              coalesce((select name from public.profiles where id = new.user_id), 'Someone') || ' replied in #' || room_name,
              left(new.body, 140), '/community/' || room_slug);
    end if;
  end if;
  return new;
end $$;

drop trigger if exists cb_on_community_message on public.community_messages;
create trigger cb_on_community_message after insert on public.community_messages
  for each row execute function public.cb_on_community_message();

create or replace function public.list_rooms()
returns table (id uuid, slug text, name text, description text, category text, is_locked boolean,
               "position" int, message_count int, last_message_at timestamptz, unread int)
language sql stable security definer set search_path = public as $$
  select r.id, r.slug, r.name, r.description, r.category, r.is_locked, r.position,
    (select count(*)::int from public.community_messages m where m.room_id = r.id),
    (select max(m.created_at) from public.community_messages m where m.room_id = r.id),
    (select count(*)::int from public.community_messages m
      where m.room_id = r.id and m.user_id <> auth.uid()
        and m.created_at > coalesce(
          (select rr.last_read_at from public.community_room_reads rr where rr.room_id = r.id and rr.user_id = auth.uid()),
          (select p.created_at from public.profiles p where p.id = auth.uid()),
          now()))
  from public.community_rooms r
  order by r.position, r.name;
$$;

create or replace function public.mark_room_read(p_room uuid)
returns void language sql security definer set search_path = public as $$
  insert into public.community_room_reads (user_id, room_id, last_read_at)
  select auth.uid(), p_room, now() where auth.uid() is not null
  on conflict (user_id, room_id) do update set last_read_at = excluded.last_read_at;
$$;

