  ('design', 'design', 'UI, UX, product design and Figma.', 'Stacks', false, 35)
on conflict (slug) do nothing;


-- =====================================================================
-- 8. DIRECT MESSAGES between any two builders
-- =====================================================================

create table if not exists public.conversations (
  id uuid primary key default gen_random_uuid(),
  user_a uuid not null references public.profiles(id) on delete cascade,
  user_b uuid not null references public.profiles(id) on delete cascade,
  created_at timestamptz not null default now(),
  last_message_at timestamptz not null default now(),
  check (user_a < user_b),
  unique (user_a, user_b)
);
alter table public.conversations enable row level security;
drop policy if exists "cb: participants read conversation" on public.conversations;
create policy "cb: participants read conversation" on public.conversations for select to authenticated
  using (auth.uid() in (user_a, user_b));

create table if not exists public.conversation_messages (
  id uuid primary key default gen_random_uuid(),
  conversation_id uuid not null references public.conversations(id) on delete cascade,
  sender_id uuid not null references public.profiles(id) on delete cascade,
  body text not null check (char_length(btrim(body)) between 1 and 4000),
  created_at timestamptz not null default now(),
  read_at timestamptz
);
create index if not exists idx_conversation_messages on public.conversation_messages (conversation_id, created_at);
alter table public.conversation_messages enable row level security;
drop policy if exists "cb: participants read messages" on public.conversation_messages;
create policy "cb: participants read messages" on public.conversation_messages for select to authenticated
  using (exists (select 1 from public.conversations c where c.id = conversation_id and auth.uid() in (c.user_a, c.user_b)));
drop policy if exists "cb: participants send messages" on public.conversation_messages;
create policy "cb: participants send messages" on public.conversation_messages for insert to authenticated
  with check (auth.uid() = sender_id
              and exists (select 1 from public.conversations c where c.id = conversation_id and auth.uid() in (c.user_a, c.user_b)));

create or replace function public.cb_on_conversation_message()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.conversations set last_message_at = new.created_at where id = new.conversation_id;
  perform public.cb_mark_active(new.sender_id);
  return new;
end $$;

drop trigger if exists cb_on_conversation_message on public.conversation_messages;
create trigger cb_on_conversation_message after insert on public.conversation_messages
  for each row execute function public.cb_on_conversation_message();

create or replace function public.start_conversation(p_other uuid)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  conv uuid;
begin
  if uid is null then raise exception 'Please sign in first.'; end if;
  if p_other is null or p_other = uid then raise exception 'Pick someone else to message.'; end if;
  if not exists (select 1 from public.profiles where id = p_other) then raise exception 'That builder doesn''t exist.'; end if;
  insert into public.conversations (user_a, user_b) values (least(uid, p_other), greatest(uid, p_other))
  on conflict (user_a, user_b) do nothing;
  select id into conv from public.conversations where user_a = least(uid, p_other) and user_b = greatest(uid, p_other);
  return conv;
end $$;

create or replace function public.list_conversations()
returns table (id uuid, other_id uuid, other_name text, other_avatar text, other_username text,
               other_role text, other_last_seen timestamptz, last_body text, last_sender uuid,
               last_message_at timestamptz, unread int)
language sql stable security definer set search_path = public as $$
  select c.id, o.id, o.name, o.avatar_url, o.username, o.primary_role,
         case when o.show_online then o.last_seen_at end,
         lm.body, lm.sender_id, c.last_message_at,
         (select count(*)::int from public.conversation_messages m
           where m.conversation_id = c.id and m.sender_id <> auth.uid() and m.read_at is null)
  from public.conversations c
  join public.profiles o on o.id = case when c.user_a = auth.uid() then c.user_b else c.user_a end
  join lateral (
    select m.body, m.sender_id from public.conversation_messages m
    where m.conversation_id = c.id order by m.created_at desc limit 1
  ) lm on true
  where auth.uid() in (c.user_a, c.user_b)
  order by c.last_message_at desc;
$$;

create or replace function public.mark_conversation_read(p_conversation uuid)
returns void language sql security definer set search_path = public as $$
  update public.conversation_messages m set read_at = now()
  where m.conversation_id = p_conversation and m.sender_id <> auth.uid() and m.read_at is null
    and exists (select 1 from public.conversations c where c.id = p_conversation and auth.uid() in (c.user_a, c.user_b));
$$;

create or replace function public.get_unread_dm_count()
returns int language sql stable security definer set search_path = public as $$
  select count(*)::int from public.conversation_messages m
  join public.conversations c on c.id = m.conversation_id
  where auth.uid() in (c.user_a, c.user_b) and m.sender_id <> auth.uid() and m.read_at is null;
$$;


