-- 9. FUNDING: programs + applications
-- =====================================================================

create table if not exists public.funding_programs (
  id uuid primary key default gen_random_uuid(),
  slug text unique,
  name text not null,
  provider text not null,
  description text,
  amount_text text,
  url text,
  tags text[] not null default '{}',
  region text not null default 'Global',
  is_internal boolean not null default false,
  is_active boolean not null default true,
  position int not null default 0,
  created_at timestamptz not null default now()
);
alter table public.funding_programs enable row level security;
drop policy if exists "cb: programs readable" on public.funding_programs;
create policy "cb: programs readable" on public.funding_programs for select to authenticated using (is_active or public.is_admin());
drop policy if exists "cb: admins manage programs" on public.funding_programs;
create policy "cb: admins manage programs" on public.funding_programs for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

create table if not exists public.funding_applications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  program_id uuid references public.funding_programs(id) on delete set null,
  project_id uuid references public.projects(id) on delete set null,
  project_name text not null check (char_length(btrim(project_name)) between 1 and 120),
  amount_requested numeric(12,2) not null check (amount_requested > 0 and amount_requested < 100000000),
  pitch text not null check (char_length(btrim(pitch)) between 20 and 4000),
  use_of_funds text not null check (char_length(btrim(use_of_funds)) between 10 and 4000),
  traction text,
  team text,
  links text,
  contact_email text,
  status text not null default 'submitted' check (status in ('submitted', 'under_review', 'approved', 'rejected')),
  admin_note text,
  reviewed_by uuid references public.profiles(id) on delete set null,
  reviewed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists idx_funding_apps_user on public.funding_applications (user_id, created_at desc);
create index if not exists idx_funding_apps_status on public.funding_applications (status, created_at desc);
alter table public.funding_applications enable row level security;
drop policy if exists "cb: read own or admin funding apps" on public.funding_applications;
create policy "cb: read own or admin funding apps" on public.funding_applications for select to authenticated
  using (auth.uid() = user_id or public.is_admin());
drop policy if exists "cb: apply for funding as yourself" on public.funding_applications;
create policy "cb: apply for funding as yourself" on public.funding_applications for insert to authenticated
  with check (auth.uid() = user_id);
drop policy if exists "cb: withdraw own pending funding app" on public.funding_applications;
create policy "cb: withdraw own pending funding app" on public.funding_applications for delete to authenticated
  using (auth.uid() = user_id and status = 'submitted');

create or replace function public.cb_funding_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    new.status := 'submitted';
    new.admin_note := null;
    new.reviewed_by := null;
    new.reviewed_at := null;
    if new.project_id is not null and not exists (
      select 1 from public.projects where id = new.project_id and owner_id = new.user_id
    ) then
      raise exception 'You can only request funding for projects you own.';
    end if;
  end if;
  new.updated_at := now();
  return new;
end $$;

drop trigger if exists cb_funding_guard on public.funding_applications;
create trigger cb_funding_guard before insert or update on public.funding_applications
  for each row execute function public.cb_funding_guard();

create or replace function public.cb_on_funding_application()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    insert into public.notifications (user_id, type, title, body, link)
    select a.user_id, 'funding_new', 'New funding application',
           coalesce((select name from public.profiles where id = new.user_id), 'A builder') || ' applied for $' ||
             to_char(new.amount_requested, 'FM999,999,999') || ' for ' || new.project_name,
           '/admin/funding'
    from public.app_admins a where a.user_id <> new.user_id;
  elsif new.status is distinct from old.status then
    insert into public.notifications (user_id, type, title, body, link)
    values (new.user_id, 'funding_status',
            case new.status
              when 'under_review' then 'Your funding application is under review'
              when 'approved' then 'Funding application approved 🎉'
              when 'rejected' then 'Funding application update'
              else 'Funding application update' end,
            new.project_name || coalesce(' — ' || new.admin_note, ''),
            '/funding');
  end if;
  return new;
end $$;

drop trigger if exists cb_on_funding_application on public.funding_applications;
create trigger cb_on_funding_application after insert or update on public.funding_applications
  for each row execute function public.cb_on_funding_application();

