-- =====================================================================
-- 10. XP, LEVELS, STREAKS, LEADERBOARD
-- =====================================================================
--  XP:  +40 per project you create
--       + the % weight of every roadmap step you finish (a full roadmap = +100)
--       +20 per team you join
--       +2 per community post (max 10 posts a day count)
--       +5 per hype your projects receive
--       +3 per active day

create or replace function public.cb_xp_table(p_since timestamptz)
returns table (user_id uuid, xp int, projects int, steps int, teams int, posts int, hypes int, days int)
language sql stable security definer set search_path = public as $$
  with
  pj as (select owner_id as uid, count(*)::int n from public.projects
         where owner_id is not null and source = 'community' and created_at >= p_since group by owner_id),
  st as (select done_by as uid, count(*)::int n, sum(weight)::int w from public.project_milestones
         where is_done and done_by is not null and done_at >= p_since group by done_by),
  tm as (select pm.user_id as uid, count(*)::int n from public.project_members pm
         join public.projects pr on pr.id = pm.project_id
         where pm.user_id is distinct from pr.owner_id and pm.joined_at >= p_since group by pm.user_id),
  po as (select x.user_id as uid, sum(least(x.n, 10))::int n from (
           select m.user_id, date_trunc('day', m.created_at) d, count(*) n from public.community_messages m
           where m.created_at >= p_since group by 1, 2) x group by x.user_id),
  hy as (select pr.owner_id as uid, count(*)::int n from public.project_upvotes v
         join public.projects pr on pr.id = v.project_id
         where v.created_at >= p_since and pr.owner_id is not null and v.user_id <> pr.owner_id group by pr.owner_id),
  dy as (select a.user_id as uid, count(*)::int n from public.activity_days a
         where a.day >= (case when p_since = '-infinity'::timestamptz then '-infinity'::date else p_since::date end)
         group by a.user_id)
  select p.id,
         (coalesce(pj.n, 0) * 40 + coalesce(st.w, 0) + coalesce(tm.n, 0) * 20 + coalesce(po.n, 0) * 2
          + coalesce(hy.n, 0) * 5 + coalesce(dy.n, 0) * 3)::int,
         coalesce(pj.n, 0), coalesce(st.n, 0), coalesce(tm.n, 0), coalesce(po.n, 0), coalesce(hy.n, 0), coalesce(dy.n, 0)
  from public.profiles p
  left join pj on pj.uid = p.id
  left join st on st.uid = p.id
  left join tm on tm.uid = p.id
  left join po on po.uid = p.id
  left join hy on hy.uid = p.id
  left join dy on dy.uid = p.id;
$$;

create or replace function public.cb_streak(p_user uuid)
returns table (current_streak int, best_streak int)
language sql stable security definer set search_path = public as $$
  with d as (select day from public.activity_days where user_id = p_user),
  g as (select day, day - (row_number() over (order by day))::int as grp from d),
  runs as (select max(day) as last_day, count(*)::int as len from g group by grp)
  select
    coalesce((select len from runs where last_day >= current_date - 1 order by last_day desc limit 1), 0),
    coalesce((select max(len) from runs), 0);
$$;

create or replace function public.get_leaderboard(p_period text default 'all', p_limit int default 20)
returns table (user_id uuid, name text, avatar_url text, username text, primary_role text,
               xp int, projects int, steps int, rank int)
language sql stable security definer set search_path = public as $$
  select x.user_id, p.name, p.avatar_url, p.username, p.primary_role, x.xp, x.projects, x.steps,
         (row_number() over (order by x.xp desc, p.created_at asc))::int
  from public.cb_xp_table(case p_period
                            when 'week' then now() - interval '7 days'
                            when 'month' then now() - interval '30 days'
                            else '-infinity'::timestamptz end) x
  join public.profiles p on p.id = x.user_id
  where x.xp > 0 and p.name is not null
  order by x.xp desc, p.created_at asc
  limit greatest(1, least(coalesce(p_limit, 20), 100));
$$;

create or replace function public.get_user_stats(p_user uuid default auth.uid())
returns json language sql stable security definer set search_path = public as $$
  with x as (select * from public.cb_xp_table('-infinity'::timestamptz) where user_id = p_user),
  s as (select * from public.cb_streak(p_user)),
  r as (select count(*)::int + 1 as rnk from public.cb_xp_table('-infinity'::timestamptz) o
        join public.profiles op on op.id = o.user_id
        where op.name is not null and o.xp > (select coalesce(xp, 0) from x))
  select json_build_object(
    'xp', coalesce((select xp from x), 0),
    'level', floor(sqrt(coalesce((select xp from x), 0) / 25.0))::int + 1,
    'level_floor_xp', (power(floor(sqrt(coalesce((select xp from x), 0) / 25.0)), 2) * 25)::int,
    'next_level_xp', (power(floor(sqrt(coalesce((select xp from x), 0) / 25.0)) + 1, 2) * 25)::int,
    'rank', (select rnk from r),
    'projects', coalesce((select projects from x), 0),
    'steps', coalesce((select steps from x), 0),
    'teams', coalesce((select teams from x), 0),
    'posts', (select count(*)::int from public.community_messages where user_id = p_user),
    'hypes', coalesce((select hypes from x), 0),
    'active_days', coalesce((select days from x), 0),
    'current_streak', (select current_streak from s),
    'best_streak', (select best_streak from s),
    'active_today', exists (select 1 from public.activity_days where user_id = p_user and day = current_date)
  );
$$;

create or replace function public.get_platform_stats()
returns json language sql stable security definer set search_path = public as $$
  select json_build_object(
    'builders', (select count(*)::int from public.profiles where name is not null),
    'projects', (select count(*)::int from public.projects),
    'community_projects', (select count(*)::int from public.projects where source = 'community'),
    'steps_shipped', (select count(*)::int from public.project_milestones where is_done),
    'online', public.get_online_count()
  );
$$;


-- =====================================================================
-- 11. ADMIN PANEL FUNCTIONS (every one checks you're an admin)
-- =====================================================================

create or replace function public.admin_overview()
returns json language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cb_require_admin();
  return json_build_object(
    'members_total', (select count(*) from public.profiles),
    'members_onboarded', (select count(*) from public.profiles where onboarded_at is not null),
    'members_new_7d', (select count(*) from public.profiles where created_at >= now() - interval '7 days'),
    'members_new_30d', (select count(*) from public.profiles where created_at >= now() - interval '30 days'),
    'members_prev_30d', (select count(*) from public.profiles where created_at >= now() - interval '60 days' and created_at < now() - interval '30 days'),
    'online_now', (select count(*) from public.profiles where last_seen_at > now() - interval '3 minutes'),
    'dau', (select count(*) from public.user_visits where day = current_date),
    'wau', (select count(distinct user_id) from public.user_visits where day > current_date - 7),
    'mau', (select count(distinct user_id) from public.user_visits where day > current_date - 30),
    'admins', (select count(*) from public.app_admins),
    'projects_total', (select count(*) from public.projects),
    'projects_community', (select count(*) from public.projects where source = 'community'),
    'projects_github', (select count(*) from public.projects where source <> 'community'),
    'projects_new_7d', (select count(*) from public.projects where source = 'community' and created_at >= now() - interval '7 days'),
    'projects_completed', (select count(*) from public.projects where source = 'community' and progress >= 100),
    'avg_progress', (select coalesce(round(avg(progress)), 0) from public.projects where source = 'community'),
    'steps_done_7d', (select count(*) from public.project_milestones where is_done and done_at >= now() - interval '7 days'),
    'posts_7d', (select count(*) from public.community_messages where created_at >= now() - interval '7 days'),
    'dms_7d', (select count(*) from public.conversation_messages where created_at >= now() - interval '7 days'),
    'applications_pending', (select count(*) from public.applications where status = 'pending'),
    'funding_pending', (select count(*) from public.funding_applications where status in ('submitted', 'under_review')),
    'funding_total', (select count(*) from public.funding_applications),
    'funding_requested', (select coalesce(sum(amount_requested), 0) from public.funding_applications where status in ('submitted', 'under_review'))
  );
end $$;

create or replace function public.admin_member_growth(p_days int default 30)
returns table (day date, joins int, total int)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
declare start_day date;
begin
  perform public.cb_require_admin();
  if p_days is null then
    select coalesce(min(created_at)::date, current_date) into start_day from public.profiles;
  else
    start_day := current_date - (greatest(p_days, 1) - 1);
  end if;
  return query
    with days as (select generate_series(start_day, current_date, interval '1 day')::date as d),
    j as (select created_at::date as d, count(*)::int as n from public.profiles where created_at::date >= start_day group by 1),
    base as (select count(*)::int as n from public.profiles where created_at::date < start_day)
    select days.d, coalesce(j.n, 0),
           ((select n from base) + sum(coalesce(j.n, 0)) over (order by days.d))::int
    from days left join j on j.d = days.d
    order by days.d;
end $$;

create or replace function public.admin_active_series(p_days int default 30)
returns table (day date, active int)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
declare start_day date;
begin
  perform public.cb_require_admin();
  if p_days is null then
    select coalesce(min(v.day), current_date) into start_day from public.user_visits v;
  else
    start_day := current_date - (greatest(p_days, 1) - 1);
  end if;
  return query
    with days as (select generate_series(start_day, current_date, interval '1 day')::date as d)
    select days.d, (select count(*)::int from public.user_visits v where v.day = days.d)
    from days order by days.d;
end $$;

create or replace function public.admin_list_members(p_search text default null, p_limit int default 50, p_offset int default 0)
returns table (id uuid, name text, username text, email text, avatar_url text, primary_role text,
               experience_level text, availability text, country text, referral_source text, interests text[],
               created_at timestamptz, last_seen_at timestamptz, last_sign_in_at timestamptz, onboarded_at timestamptz,
               is_admin boolean, projects int, total_count int)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
declare q text := nullif(btrim(coalesce(p_search, '')), '');
begin
  perform public.cb_require_admin();
  return query
    with f as (
      select p.*, u.email::text as email, u.last_sign_in_at as last_sign_in_at
      from public.profiles p
      left join auth.users u on u.id = p.id
      where q is null
         or p.name ilike '%' || q || '%'
         or p.username ilike '%' || q || '%'
         or u.email ilike '%' || q || '%'
         or p.primary_role ilike '%' || q || '%'
         or p.country ilike '%' || q || '%'
    )
    select f.id, f.name, f.username, f.email, f.avatar_url, f.primary_role, f.experience_level, f.availability,
           f.country, f.referral_source, f.interests, f.created_at, f.last_seen_at, f.last_sign_in_at, f.onboarded_at,
           exists (select 1 from public.app_admins a where a.user_id = f.id),
           (select count(*)::int from public.projects pr where pr.owner_id = f.id),
           (count(*) over ())::int
    from f
    order by f.created_at desc
    limit greatest(1, least(coalesce(p_limit, 50), 200)) offset greatest(coalesce(p_offset, 0), 0);
end $$;

create or replace function public.admin_set_admin(p_user uuid, p_make boolean)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform public.cb_require_admin();
  if p_make then
    insert into public.app_admins (user_id, added_by) values (p_user, auth.uid()) on conflict do nothing;
    if found then
      insert into public.notifications (user_id, type, title, body, link)
      values (p_user, 'admin_granted', 'You''re now an admin', 'You can open the admin panel from the menu.', '/admin');
    end if;
  else
    if (select count(*) from public.app_admins) <= 1 then
      raise exception 'You can''t remove the last admin.';
    end if;
    delete from public.app_admins where user_id = p_user;
  end if;
end $$;

create or replace function public.admin_add_admin_by_email(p_email text)
returns uuid language plpgsql security definer set search_path = public as $$
declare target uuid;
begin
  perform public.cb_require_admin();
  select u.id into target from auth.users u where lower(u.email) = lower(btrim(p_email));
  if target is null then
    raise exception 'No account uses that email yet. Ask them to sign up first.';
  end if;
  begin
    insert into public.profiles (id) values (target) on conflict do nothing;
  exception when others then
    null;
  end;
  if not exists (select 1 from public.profiles where id = target) then
    raise exception 'That person has signed up but not finished setting up their profile yet.';
  end if;
  perform public.admin_set_admin(target, true);
  return target;
end $$;

create or replace function public.admin_insights()
returns json language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cb_require_admin();
  return json_build_object(
    'total', (select count(*) from public.profiles),
    'onboarded', (select count(*) from public.profiles where onboarded_at is not null),
    'roles', (select coalesce(json_agg(json_build_object('label', label, 'count', n) order by n desc), '[]'::json)
              from (select coalesce(primary_role, 'Not set') label, count(*)::int n from public.profiles group by 1) x),
    'experience', (select coalesce(json_agg(json_build_object('label', label, 'count', n) order by n desc), '[]'::json)
              from (select coalesce(experience_level, 'Not set') label, count(*)::int n from public.profiles group by 1) x),
    'availability', (select coalesce(json_agg(json_build_object('label', label, 'count', n) order by n desc), '[]'::json)
              from (select coalesce(availability, 'Not set') label, count(*)::int n from public.profiles group by 1) x),
    'countries', (select coalesce(json_agg(json_build_object('label', label, 'count', n) order by n desc), '[]'::json)
              from (select coalesce(country, 'Not set') label, count(*)::int n from public.profiles group by 1) x),
    'referral', (select coalesce(json_agg(json_build_object('label', label, 'count', n) order by n desc), '[]'::json)
              from (select coalesce(referral_source, 'Not set') label, count(*)::int n from public.profiles group by 1) x),
    'interests', (select coalesce(json_agg(json_build_object('label', label, 'count', n) order by n desc), '[]'::json)
              from (select i label, count(*)::int n from public.profiles, unnest(interests) i group by 1) x),
    'skills', (select coalesce(json_agg(json_build_object('label', label, 'count', n) order by n desc), '[]'::json)
              from (select s.name label, count(*)::int n from public.user_skills us join public.skills s on s.id = us.skill_id
                    group by 1 order by 2 desc limit 20) x),
    'categories', (select coalesce(json_agg(json_build_object('label', label, 'count', n) order by n desc), '[]'::json)
              from (select coalesce(category, 'Uncategorised') label, count(*)::int n from public.projects
                    where source = 'community' group by 1) x)
  );
end $$;

create or replace function public.admin_recent_activity(p_limit int default 40)
returns table (kind text, actor_id uuid, actor_name text, actor_avatar text, summary text, link text, at timestamptz)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
begin
  perform public.cb_require_admin();
  return query
  select * from (
    select 'signup'::text, p.id, p.name, p.avatar_url, 'joined Cobuild'::text, ('/u/' || p.id)::text, p.created_at
      from public.profiles p
    union all
    select 'project', pr.owner_id, o.name, o.avatar_url, 'created ' || pr.title, '/project/' || pr.id, pr.created_at
      from public.projects pr left join public.profiles o on o.id = pr.owner_id where pr.source = 'community'
    union all
    select 'step', m.done_by, o.name, o.avatar_url, 'finished "' || m.title || '" in ' || pr.title, '/project/' || pr.id, m.done_at
      from public.project_milestones m join public.projects pr on pr.id = m.project_id
      left join public.profiles o on o.id = m.done_by where m.is_done
    union all
    select 'team', pm.user_id, o.name, o.avatar_url, 'joined the team of ' || pr.title, '/project/' || pr.id, pm.joined_at
      from public.project_members pm join public.projects pr on pr.id = pm.project_id
      left join public.profiles o on o.id = pm.user_id where pm.user_id is distinct from pr.owner_id
    union all
    select 'post', c.user_id, o.name, o.avatar_url, 'posted in #' || r.slug, '/community/' || r.slug, c.created_at
      from public.community_messages c join public.community_rooms r on r.id = c.room_id
      left join public.profiles o on o.id = c.user_id
    union all
    select 'funding', f.user_id, o.name, o.avatar_url, 'applied for funding for ' || f.project_name, '/admin/funding', f.created_at
      from public.funding_applications f left join public.profiles o on o.id = f.user_id
  ) a
  order by 7 desc nulls last
  limit greatest(1, least(coalesce(p_limit, 40), 200));
end $$;

create or replace function public.admin_set_featured(p_project uuid, p_featured boolean)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform public.cb_require_admin();
  update public.projects set is_featured = coalesce(p_featured, false) where id = p_project;
end $$;

create or replace function public.admin_review_funding(p_id uuid, p_status text, p_note text default null)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform public.cb_require_admin();
  if p_status not in ('submitted', 'under_review', 'approved', 'rejected') then
    raise exception 'Unknown status.';
  end if;
  update public.funding_applications
     set status = p_status,
         admin_note = nullif(btrim(coalesce(p_note, '')), ''),
         reviewed_by = auth.uid(),
         reviewed_at = now()
   where id = p_id;
end $$;

create or replace function public.admin_broadcast(p_title text, p_body text)
returns int language plpgsql security definer set search_path = public as $$
declare n int;
begin
  perform public.cb_require_admin();
  if coalesce(btrim(p_title), '') = '' then raise exception 'Add a title.'; end if;
  insert into public.notifications (user_id, type, title, body, link)
  select p.id, 'broadcast', left(btrim(p_title), 120), nullif(left(btrim(coalesce(p_body, '')), 500), ''), '/notifications'
  from public.profiles p;
  get diagnostics n = row_count;
  return n;
end $$;

-- Upsert projects found outside the app (GitHub repos, design calls, ...) by URL.
-- items: [{ t: title, d: description, u: url, o: owner/org, s: stars, l: language, c: category,
--           k: [tech], r: [roles], h: homepage, x: open-tasks link, src: where we found it }]
-- Roles are only ever added, never removed, so re-running an older import keeps newer roles.
create or replace function public.admin_import_projects(p_items jsonb)
returns int language plpgsql security definer set search_path = public as $$
declare
  item jsonb;
  pid uuid;
  is_gh boolean;
  n int := 0;
begin
  -- auth.uid() is null only when run from the SQL editor (anon can't execute this function).
  if auth.uid() is not null then perform public.cb_require_admin(); end if;
  if jsonb_typeof(p_items) is distinct from 'array' then raise exception 'Expected a list of projects.'; end if;

  for item in select * from jsonb_array_elements(p_items) loop
    continue when coalesce(item->>'u', '') !~ '^https://[^\s]+$' or coalesce(btrim(item->>'t'), '') = '';
    is_gh := (item->>'u') ~ '^https://github\.com/[^/]+/[^/]+$';

    insert into public.projects (owner_id, title, tagline, description, category, stage, status, tech_stack,
                                 repo_url, demo_url, source, external_url, external_owner, external_stars,
                                 external_language, external_contribute_url, external_source)
    values (
      null,
      left(item->>'t', 80),
      null,
      left(coalesce(item->>'d', ''), 4000),
      item->>'c',
      'launched',
      'open',
      coalesce((select array_agg(x) from jsonb_array_elements_text(coalesce(item->'k', '[]')) x), '{}'),
      case when is_gh then item->>'u' end,
      case when coalesce(item->>'h', '') ~ '^https?://' then item->>'h' end,
      case when is_gh then 'github' else 'external' end,
      item->>'u',
      item->>'o',
      nullif(item->>'s', '')::int,
      nullif(item->>'l', ''),
      case when coalesce(item->>'x', '') ~ '^https://[^\s]+$' then item->>'x' end,
      coalesce(nullif(item->>'src', ''), case when is_gh then 'GitHub' else 'Web' end)
    )
    on conflict (external_url) where external_url is not null do update set
      description = excluded.description,
      category = excluded.category,
      tech_stack = excluded.tech_stack,
      demo_url = coalesce(excluded.demo_url, projects.demo_url),
      external_stars = excluded.external_stars,
      external_language = excluded.external_language,
      external_contribute_url = coalesce(excluded.external_contribute_url, projects.external_contribute_url),
      external_source = case when projects.external_source is null or projects.external_source = 'GitHub'
                             then excluded.external_source else projects.external_source end
    returning id into pid;

    insert into public.project_roles_needed (project_id, role_name)
    select pid, r from (select distinct btrim(r) as r from jsonb_array_elements_text(coalesce(item->'r', '[]')) r) s
    where s.r <> ''
      and not exists (select 1 from public.project_roles_needed e where e.project_id = pid and lower(e.role_name) = lower(s.r));

    n := n + 1;
  end loop;
  return n;
end $$;


-- =====================================================================
-- 12. PERMISSIONS: the app only ever calls these as a signed-in user
-- =====================================================================

do $$
declare f record;
begin
  for f in
    select p.oid::regprocedure as sig
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname in (
        'touch_presence', 'get_online_count', 'create_project', 'update_project', 'delete_project',
        'set_milestone_done', 'list_rooms', 'mark_room_read', 'start_conversation', 'list_conversations',
        'mark_conversation_read', 'get_unread_dm_count', 'get_leaderboard', 'get_user_stats', 'get_platform_stats',
        'admin_overview', 'admin_member_growth', 'admin_active_series', 'admin_list_members', 'admin_set_admin',
        'admin_add_admin_by_email', 'admin_insights', 'admin_recent_activity', 'admin_set_featured',
        'admin_review_funding', 'admin_broadcast', 'admin_import_projects', 'is_admin'
      )
  loop
    execute format('revoke all on function %s from public, anon', f.sig);
    execute format('grant execute on function %s to authenticated, service_role', f.sig);
  end loop;

  -- Internal helpers: never callable from the app.
  for f in
    select p.oid::regprocedure as sig
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname in ('cb_mark_active', 'cb_xp_table', 'cb_streak', 'cb_require_admin', 'cb_validate_project', 'cb_clean_url')
  loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
  end loop;
end $$;


-- =====================================================================
-- 13. REALTIME (live chat, live progress bars, live notifications)
-- =====================================================================

do $$
declare t text;
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    foreach t in array array['messages', 'direct_messages', 'notifications', 'community_messages',
                             'conversation_messages', 'project_milestones', 'community_message_likes']
    loop
      if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
        execute format('alter publication supabase_realtime add table public.%I', t);
      end if;
    end loop;
  end if;
end $$;


-- =====================================================================
-- 14. ONE-TIME RESET: delete every existing project
-- =====================================================================

create table if not exists public.cb_migrations (
  key text primary key,
  ran_at timestamptz not null default now()
);
alter table public.cb_migrations enable row level security;

do $$
begin
  if not exists (select 1 from public.cb_migrations where key = 'reset_projects_2026_10') then
    delete from public.notifications where project_id is not null;
    delete from public.projects;  -- cascades to roles, members, applications, chats, roadmaps, saves, hypes
    insert into public.cb_migrations (key) values ('reset_projects_2026_10');
  end if;
end $$;


